args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?husband ?husbandLabel ?birthPlace ?birthPlaceLabel WHERE {
  dbr:Virginia_Foster_Durr dbo:spouse ?husband .
  ?husband dbo:birthPlace ?birthPlace .
  OPTIONAL { ?husband rdfs:label ?husbandLabel . FILTER (lang(?husbandLabel) = 'en') }
  OPTIONAL { ?birthPlace rdfs:label ?birthPlaceLabel . FILTER (lang(?birthPlaceLabel) = 'en') }
}

